import{promises as fs}from'node:fs';for(const p of['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Repo kökünde çalıştır.`)});const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};await append('scripts/build.mjs','v23-1-build-patch.txt','V23.1 force repaired audio reader');await append('assets/atlas.css','v23-1-css-patch.txt','V23.1 audio repair status');await fs.copyFile('article-reader-v231.js','assets/article-reader-v231.js');console.log('V23.1 kuruldu: ses listesi, metin seçimi ve Android başlatma hatası onarıldı.');
